104	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
105	     * code are kept when present; otherwise country code '+61' is assumed and a
106	     * single leading '0' is dropped from the national digits. The result must have
107	     * between 8 and 15 digits after the '+'.
108	     *
109	     * <p>When the caller supplies the country code explicitly (a leading '+'), the
110	     * national-number length is additionally validated against that country code:
111	     * '+61' requires 9 national digits and '+1' requires 10. A number whose national
112	     * length is wrong for its country is rejected.
113	     *
114	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
115	     */
116	    static String toE164(String raw) {
117	        if (raw == null) {
118	            return null;
119	        }
120	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
121	        String digits;
122	        boolean explicitCountryCode;
123	        if (cleaned.startsWith("+")) {
124	            digits = cleaned.substring(1);
125	            explicitCountryCode = true;
126	        } else {
127	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
128	            digits = "61" + national;
129	            explicitCountryCode = false;
130	        }
131	        if (!digits.matches("[0-9]{8,15}")) {
132	            return null;
133	        }
134	        if (explicitCountryCode && !hasValidNationalLength(digits)) {
135	            return null;
136	        }
137	        return "+" + digits;
138	    }
139	
140	    /**
141	     * Validate the national-number length of an E.164 number (its digits without the
142	     * leading '+') against the requirement for its country code: country code '+61'
143	     * (Australia) requires 9 national digits and '+1' (NANP) requires 10. Country codes
144	     * without a configured length requirement are accepted unchanged.
145	     */
146	    private static boolean hasValidNationalLength(String digits) {
147	        if (digits.startsWith("61")) {
148	            return digits.length() - "61".length() == 9;
149	        }
150	        if (digits.startsWith("1")) {
151	            return digits.length() - "1".length() == 10;
152	        }
153	        return true;
154	    }
155	
156	    /**
157	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
158	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
159	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
160	     * input normalises to the empty string.
161	     */
162	    private static String normaliseIdentity(String value) {
163	        if (value == null) {
164	            return "";
165	        }
166	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
167	    }
168	
169	    /**
170	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
171	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
172	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
173	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
174	     * that is both stored and used for every address comparison.
175	     */
176	    static String normaliseAddress(String value) {
177	        if (value == null) {
178	            return "";
179	        }
180	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
181	        if (collapsed.isEmpty()) {
182	            return "";
183	        }
184	        String[] tokens = collapsed.split(" ");
185	        StringBuilder result = new StringBuilder();
186	        for (int i = 0; i < tokens.length; i++) {
187	            if (i > 0) {
188	                result.append(' ');
189	            }
190	            result.append(expandAddressAbbreviation(tokens[i]));
191	        }
192	        return result.toString();
193	    }
194	
195	    /**
196	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
197	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
198	     * returned unchanged.
199	     */
200	    private static String expandAddressAbbreviation(String token) {
201	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
202	        return switch (core) {
203	            case "ST" -> "STREET";
204	            case "RD" -> "ROAD";
205	            case "AVE" -> "AVENUE";
206	            default -> token;
207	        };
208	    }
209	
210	    /**
211	     * Derive the stable, shared household identifier for owners in the same household: the first 12
212	     * lower-case hex characters of the SHA-256 digest over {@code '<normalizedLastName>|<postcode>'},
213	     * so every owner with the same last name and postcode resolves to the same value regardless of
214	     * the order in which they were created.
215	     */
216	    private static String householdId(String lastNameKey, String postcode) {
217	        return hashHex(lastNameKey + "|" + (postcode == null ? "" : postcode), 12, false);
218	    }
219	
220	    /**
221	     * Count how many owners belong to the given owner's household (owners sharing its normalized last
222	     * name and postcode). An owner without a postcode has no household peers and counts as a household
223	     * of one.
224	     */
225	    private int householdSize(Owner owner) {
226	        if (owner.getPostcode() == null) {
227	            return 1;
228	        }
229	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
230	        return (int) this.clinicService.findAllOwners().stream()
231	            .filter(existing -> existing.getPostcode() != null
232	                && householdId.equals(
233	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
234	            .count();
235	    }
236	
237	    /**
238	     * Build an owner's derived duplicate-detection identity key as
239	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Each {@code null}
240	     * component contributes the empty string, and the email is lower-cased so the comparison is
241	     * case-insensitive. Two owners are duplicates only when their whole identity keys are equal.
242	     */
243	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
244	        String telephone = normalizedTelephone == null ? "" : normalizedTelephone;
245	        String emailKey = email == null ? "" : email.toLowerCase();
246	        String household = householdId == null ? "" : householdId;
247	        return telephone + "|" + emailKey + "|" + household;
248	    }
249	
250	    /**
251	     * Build the customer code for a new owner as {@code '<REGION>-<HASH8>'}, where REGION is the region
252	     * code derived from the postcode (falling back to the city-to-region table, else {@code "UNKNOWN"})
253	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over
254	     * {@code normalizedTelephone + lastName}. Sequence numbers are no longer used, so the code depends
255	     * only on the owner's own region and identity, not on how many owners already exist.
256	     */
257	    private String nextCustomerCode(String region, String normalizedTelephone, String lastName) {
258	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
259	    }
260	
261	    /**
262	     * De-duplicate a computed customer code against the codes already assigned to existing owners:
263	     * when {@code code} is unused it is returned unchanged, otherwise {@code '-<n>'} is appended with
264	     * the smallest {@code n} of 2 or more that makes the result unique among existing owners.
265	     */
266	    private String deduplicateCustomerCode(String code) {
267	        Set<String> existing = this.clinicService.findAllOwners().stream()
268	            .map(Owner::getCustomerCode)
269	            .filter(Objects::nonNull)
270	            .collect(Collectors.toSet());
271	        if (!existing.contains(code)) {
272	            return code;
273	        }
274	        int n = 2;
275	        while (existing.contains(code + "-" + n)) {
276	            n++;
277	        }
278	        return code + "-" + n;
279	    }
280	
281	    /**
282	     * First 8 upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input}.
283	     */
284	    private static String hash8(String input) {
285	        return hashHex(input, 8, true);
286	    }
287	
288	    /**
289	     * First {@code length} hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input},
290	     * upper-cased when {@code upperCase} is true and lower-cased otherwise.
291	     */
292	    private static String hashHex(String input, int length, boolean upperCase) {
293	        try {
294	            byte[] digest = MessageDigest.getInstance("SHA-256")
295	                .digest(input.getBytes(StandardCharsets.UTF_8));
296	            StringBuilder sb = new StringBuilder(digest.length * 2);
297	            for (byte b : digest) {
298	                sb.append(String.format("%02x", b));
299	            }
300	            String hex = sb.substring(0, length);
301	            return upperCase ? hex.toUpperCase() : hex;
302	        }
303	        catch (java.security.NoSuchAlgorithmException e) {
304	            throw new IllegalStateException(e);
305	        }
306	    }
307	
308	    /**
309	     * Resolve an owner's region preferring the postcode: the region is taken from the postcode range
310	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) when the postcode resolves, otherwise from the
311	     * fixed city-to-region table, else {@code "UNKNOWN"}.
312	     */
313	    private static String region(String postcode, String city) {
314	        String fromPostcode = regionForPostcode(postcode);
315	        return fromPostcode != null ? fromPostcode : regionForCity(city);
316	    }
317	
318	    /**
319	     * Region for a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
320	     * or {@code null} when the postcode is absent, not exactly 4 digits, or in no known range.
321	     */
322	    private static String regionForPostcode(String postcode) {
323	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
324	            return null;
325	        }
326	        int value = Integer.parseInt(postcode);
327	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
328	            int[] range = entry.getValue();
329	            if (value >= range[0] && value <= range[1]) {
330	                return entry.getKey();
331	            }
332	        }
333	        return null;
334	    }
335	
336	    /**
337	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
338	     * Sunday it is advanced to the following Monday; weekday dates are returned unchanged.
339	     */
340	    static LocalDate toBusinessDay(LocalDate date) {
341	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
342	            date = date.plusDays(1);
343	        }
344	        return date;
345	    }
346	
347	    /**
348	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
349	     * using the same per-day accumulation path as the daily create-limit rule.
350	     */
351	    private long ownersCreatedOn(LocalDate registrationDate) {
352	        LocalDate day = toBusinessDay(registrationDate);
353	        return this.clinicService.findAllOwners().stream()
354	            .map(Owner::getRegistrationDate)
355	            .filter(existing -> existing != null)
356	            .map(OwnerRestControllerV1::toBusinessDay)
357	            .filter(day::equals)
358	            .count();
359	    }
360	
361	    /**
362	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
363	     * postcode against the owner's city region.
364	     */
365	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
366	        "NSW", new int[] {2000, 2099},
367	        "VIC", new int[] {3000, 3099},
368	        "QLD", new int[] {4000, 4099});
369	
370	    /**
371	     * Resolve an owner's region from the city using the fixed city-to-region table
372	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}); {@code "UNKNOWN"}
373	     * when the city is not listed.
374	     */
375	    private static String regionForCity(String city) {
376	        return switch (city == null ? "" : city) {
377	            case "Sydney" -> "NSW";
378	            case "Melbourne" -> "VIC";
379	            case "Brisbane" -> "QLD";
380	            default -> "UNKNOWN";
381	        };
382	    }
383	
384	    /**
385	     * Validate a supplied postcode: it must be exactly 4 digits, and when the owner's city maps to a
386	     * known region the numeric value must fall within that region's inclusive range (NSW 2000-2099,
387	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
388	     */
389	    private static boolean isPostcodeValid(String postcode, String city) {
390	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
391	            return false;
392	        }
393	        int[] range = REGION_POSTCODES.get(regionForCity(city));
394	        if (range == null) {
395	            return true;
396	        }
397	        int value = Integer.parseInt(postcode);
398	        return value >= range[0] && value <= range[1];
399	    }
400	
401	    /**
402	     * Whether the email's domain (the part after the final '@') is on the disposable-domain
403	     * blocklist. A {@code null} email is not disposable; the comparison is case-insensitive.
404	     */
405	    private static boolean isDisposableEmailDomain(String email) {
406	        if (email == null) {
407	            return false;
408	        }
409	        int at = email.lastIndexOf('@');
410	        if (at < 0 || at == email.length() - 1) {
411	            return false;
412	        }
413	        String domain = email.substring(at + 1).toLowerCase();
414	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
415	    }
