447	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
448	    @Override
449	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
450	        String telephone = toE164(ownerFieldsDto.getTelephone());
451	        if (telephone == null) {
452	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
453	        }
454	        String email = ownerFieldsDto.getEmail();
455	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
456	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
457	        }
458	        if (isDisposableEmailDomain(email)) {
459	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
460	        }
461	        // Structured address is preferred when supplied (a non-blank 'addressLine1'); otherwise the
462	        // flat 'address' input is used for backward compatibility. Normalization applies to whichever
463	        // fields are supplied, and the composed 'address' is the normalized addressLine1 with the
464	        // normalized addressLine2 appended after a single space when present.
465	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
466	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
467	        boolean structuredAddress = !addressLine1.isEmpty();
468	        String address;
469	        if (structuredAddress) {
470	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
471	        } else {
472	            address = normaliseAddress(ownerFieldsDto.getAddress());
473	        }
474	        if (address.isEmpty()) {
475	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
476	        }
477	        String postcode = ownerFieldsDto.getPostcode();
478	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
479	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
480	        }
481	        if (ownerFieldsDto.getRegistrationDate() != null
482	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
483	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
484	        }
485	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
486	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
487	        LocalDate registrationDate = toBusinessDay(effectiveDate);
488	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
489	            .map(Owner::getRegistrationDate)
490	            .filter(existing -> existing != null)
491	            .map(OwnerRestControllerV1::toBusinessDay)
492	            .filter(registrationDate::equals)
493	            .count();
494	        if (ownersCreatedThatDay >= 100) {
495	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
496	        }
497	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
498	        long ownersInCity = this.clinicService.findAllOwners().stream()
499	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
500	            .count();
501	        if (ownersInCity >= 50) {
502	            return new ResponseEntity<>(HttpStatus.CONFLICT);
503	        }
504	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
505	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
506	        // The household is deterministically keyed on (normalized last name, postcode): every owner
507	        // with a postcode belongs to the household identified by this computed id, and owners sharing
508	        // a last name and postcode share it automatically.
509	        String householdId = (postcode == null) ? null : householdId(lastNameKey, postcode);
510	        // Existing owners already in this household (same last name and postcode).
511	        List<Owner> householdMembers = (householdId == null) ? List.of()
512	            : this.clinicService.findAllOwners().stream()
513	                .filter(existing -> householdId.equals(
514	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
515	                .toList();
516	        // A second owner in an existing household is a household duplicate: rejected with 409 unless
517	        // it declares 'sharesHousehold', which only bypasses this block (the household link itself is
518	        // already assigned deterministically above).
519	        if (!householdMembers.isEmpty() && !sharesHousehold) {
520	            return new ResponseEntity<>(HttpStatus.CONFLICT);
521	        }
522	        String identityKey = identityKey(telephone, email, householdId);
523	        boolean identityInUse = this.clinicService.findAllOwners().stream()
524	            .anyMatch(existing -> identityKey(toE164(existing.getTelephone()),
525	                existing.getEmail(), existing.getHouseholdId()).equals(identityKey));
526	        if (identityInUse) {
527	            return new ResponseEntity<>(HttpStatus.CONFLICT);
528	        }
529	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
530	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
531	            .filter(existing ->
532	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
533	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
534	            .count();
535	        HttpHeaders headers = new HttpHeaders();
536	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
537	        owner.setNamesakeCount(namesakeCount);
538	        owner.setAddress(address);
539	        if (structuredAddress) {
540	            owner.setAddressLine1(addressLine1);
541	            owner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
542	        } else {
543	            owner.setAddressLine1(null);
544	            owner.setAddressLine2(null);
545	        }
546	        owner.setTelephone(telephone);
547	        owner.setEmail(email == null ? null : email.toLowerCase());
548	        owner.setRegistrationDate(registrationDate);
549	        owner.setCustomerCode(deduplicateCustomerCode(nextCustomerCode(
550	            region(postcode, owner.getCity()), telephone, owner.getLastName())));
551	        owner.setHouseholdId(householdId);
552	        // A created owner is never flagged as a suspected duplicate: a lone owner has no household
553	        // peer, and a same-household owner can only be created by declaring 'sharesHousehold', which
554	        // makes it an intentional household member rather than a suspected duplicate.
555	        owner.setPossibleDuplicateOf(null);
556	        this.clinicService.saveOwner(owner);
557	        owner.setHouseholdSize(householdSize(owner));
558	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
559	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
560	            ownerMapper.formatMembershipLevel(owner), ownerMapper.formatMembershipNumber(owner));
561	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
562	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
563	        headers.setLocation(UriComponentsBuilder.newInstance()
564	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
565	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
566	    }
